pub fn place(arr: Vec<f32>, mask: Vec<bool>, vals: Vec<f32>) -> Vec<f32> {
    assert_eq!(
        arr.len(),
        mask.len(),
        "The input array and mask must have the same length"
    );
    assert!(
        !vals.is_empty(),
        "Values array must be non-empty to provide replacements"
    );

    let mut result = Vec::with_capacity(arr.len());
    let mut val_idx = 0;
    let vals_len = vals.len();

    for (a, &m) in arr.into_iter().zip(mask.iter()) {
        if m {
            // Use the next replacement value in a cyclic fashion
            result.push(vals[val_idx]);
            val_idx = (val_idx + 1) % vals_len;
        } else {
            // Preserve the original value
            result.push(a);
        }
    }

    result
}

