        let mask = vec![false, true, false, true, true];
        let vals = vec![10.0, 20.0];
        // mask says: keep 1.0, replace with 10.0, keep 3.0, replace with 20.0, replace with 10.0 (cycle)
        let expected = vec![1.0, 10.0, 3.0, 20.0, 10.0];
